"use strict";(self.webpackChunkgrc=self.webpackChunkgrc||[]).push([[44967],{3454:e=>{e.exports=JSON.parse('{"title":"Characterizing Dataflow for I/O-Aware Scheduling in HPC Workflows","authors":["M. Tang","L. Guo","A. Kougkas","X.-H. Sun","N. R. Tallent"],"venue":"40th IEEE International Parallel & Distributed Processing Symposium (IPDPS 2026)","type":"Conference","date":"May, 2026","month":5,"year":2026,"tags":["HPC Analysis","I/O","Workflow Optimization","Data Analytics","Performance Measurement"],"links":{"pdf":"http://cs.iit.edu/~scs/assets/files/tang2026characterizing.pdf","bibtex":"http://cs.iit.edu/~scs/assets/files/tang2026characterizing.bib","citation":"http://cs.iit.edu/~scs/assets/files/tang2026characterizing.txt"},"doi":"10.1109/IPDPS65963.2026.00076","abstract":"Scientific discoveries are increasingly facilitated by data-driven workflows executed in HPC environments, where complex task-to-data exchange patterns cause bottlenecks in shared storage. Existing I/O-aware scheduling techniques use application-oriented metrics that primarily focus on individual task characteristics, leaving workflow-level dataflow behaviors\u2014such as file reuse and producer\u2013consumer I/O patterns\u2014underexplored despite their importance for effective orchestration. This paper presents a workflow-centric methodology to characterize and analyze I/O using workflow-specific patterns and metrics. By correlating workflow structures (e.g., task composition, execution order, and producer\u2013consumer relationships) with I/O metrics (e.g., access type, operation count, and data size), we gain deeper insight into workflow I/O dynamics. We evaluate our approach on six diverse HPC workflows, covering 3,500 task instances and 1,387 unique files, with a total I/O volume of 1.5 TB. This analysis uncovers a spectrum of behaviors related to file reuse, data exchange, and task-level I/O heterogeneity. These insights reveal new opportunities and research directions for I/O-aware scheduling, supporting smarter task placement, data movement, and storage selection in HPC.","slug":"tang-2026-dataflow-workflow-b4e1"}')}}]);